\set ON_ERROR_STOP on
BEGIN;
DO $patch$
DECLARE s jsonb; item jsonb; v_course bigint; v_lesson bigint; v_quiz bigint;
        v_count int; v_q bigint; v_attempts int; i int; j int;
BEGIN
 SELECT course_id INTO STRICT v_course FROM lms.courses
 WHERE course_name='Phân tích thiết kế hệ thống' AND NOT is_deleted;
 FOR s IN SELECT value FROM jsonb_array_elements($bank$[{"order":2,"questions":[{"text":"Mục tiêu cốt lõi của phân tích hệ thống là gì?","options":["Chọn màu giao diện đầu tiên","Cài đặt máy chủ sản xuất","Hiểu vấn đề và xác định yêu cầu cần đáp ứng","Viết mã nguồn trước khi khảo sát"],"correct":2},{"text":"Khảo sát hiện trạng (AS-IS) tập trung mô tả điều gì?","options":["Ngân sách bảo trì sau triển khai","Quy trình nghiệp vụ đang diễn ra","Giải pháp sẽ xây dựng trong tương lai","Mã nguồn của hệ thống mới"],"correct":1},{"text":"Sản phẩm đầu ra phù hợp của giai đoạn khảo sát là gì?","options":["Tài liệu hiện trạng và nhu cầu các bên liên quan","Bản ứng dụng đã phát hành","Bộ mã nguồn hoàn chỉnh","Tệp thực thi của hệ thống"],"correct":0},{"text":"Phỏng vấn và quan sát người dùng giúp nhóm dự án điều gì?","options":["Thay thế toàn bộ kiểm thử","Loại bỏ việc ghi tài liệu","Đảm bảo hệ thống không bao giờ lỗi","Xác thực nhu cầu và phát hiện ngoại lệ nghiệp vụ"],"correct":3},{"text":"Quy trình TO-BE có mục đích gì?","options":["Liệt kê thiết bị cũ","Thống kê dung lượng ổ cứng","Mô tả quy trình đề xuất sau cải tiến","Ghi lại lịch sử lỗi máy chủ"],"correct":2},{"text":"Ai là stakeholder của một hệ thống quản lý bán hàng?","options":["Chỉ người viết tài liệu kỹ thuật","Người hoặc tổ chức ảnh hưởng hay chịu tác động bởi hệ thống","Chỉ lập trình viên giao diện","Chỉ người mua máy chủ"],"correct":1},{"text":"Khi hai phòng ban có yêu cầu mâu thuẫn, cách xử lý phù hợp là gì?","options":["Làm rõ ưu tiên, ghi nhận và thống nhất với các bên","Tự ý bỏ một yêu cầu không báo","Phát triển cả hai mà không xem tác động","Ngừng phân tích và chuyển sang lập trình"],"correct":0}]},{"order":3,"questions":[{"text":"Yêu cầu chức năng mô tả điều gì?","options":["Số lượng máy tính của nhóm phát triển","Hệ thống phải thực hiện những chức năng nào","Mức độ tiêu thụ điện của thiết bị","Màu sắc của logo công ty"],"correct":1},{"text":"Ví dụ nào là yêu cầu phi chức năng?","options":["95% yêu cầu tìm kiếm phản hồi trong dưới 2 giây","Người dùng có thể tạo đơn hàng","Nhân viên có thể xuất hóa đơn","Quản trị viên có thể khóa tài khoản"],"correct":0},{"text":"Yêu cầu có thể kiểm thử cần có đặc điểm gì?","options":["Chỉ cần diễn đạt bằng lời chung chung","Không được gắn với đối tượng sử dụng","Luôn phải mô tả bằng sơ đồ lớp","Có tiêu chí chấp nhận rõ ràng và đo được"],"correct":3},{"text":"Ma trận truy vết yêu cầu dùng để làm gì?","options":["Tính chi phí điện cho máy chủ","Nén kích thước tệp dự án","Liên kết yêu cầu với thiết kế và ca kiểm thử","Đổi tên bảng dữ liệu tự động"],"correct":2},{"text":"Khi phát hiện một yêu cầu chưa rõ, việc nên làm trước là gì?","options":["Thay bằng một yêu cầu bất kỳ","Trao đổi với bên liên quan để làm rõ","Tự đoán và đưa vào bản chính thức","Bỏ qua cho tới khi triển khai"],"correct":1},{"text":"Điều kiện chấp nhận giúp xác định điều gì?","options":["Khi nào yêu cầu được coi là đáp ứng","Ai sở hữu máy tính xách tay","Màu nền của bản trình bày","Phiên bản hệ điều hành người phân tích"],"correct":0},{"text":"Ưu tiên yêu cầu dựa trên yếu tố nào là phù hợp?","options":["Thứ tự chữ cái của tên chức năng","Số ký tự trong mô tả","Màu sắc đánh dấu trong tài liệu","Giá trị nghiệp vụ, rủi ro và nguồn lực"],"correct":3}]},{"order":4,"questions":[{"text":"BPMN dùng chủ yếu để biểu diễn điều gì?","options":["Luồng công việc và quy trình nghiệp vụ","Chi tiết cấu trúc CPU","Định dạng ảnh của ứng dụng","Cú pháp câu lệnh SQL"],"correct":0},{"text":"Trong BPMN, gateway biểu diễn điều gì?","options":["Một tệp lưu trữ trên máy chủ","Một bảng dữ liệu bắt buộc","Một màn hình đăng nhập","Điểm rẽ nhánh hoặc hợp nhất luồng theo điều kiện"],"correct":3},{"text":"Swimlane trong sơ đồ quy trình giúp làm rõ điều gì?","options":["Độ phân giải biểu tượng","Kích thước mã nguồn","Vai trò hoặc bộ phận chịu trách nhiệm cho hoạt động","Dung lượng RAM cần thiết"],"correct":2},{"text":"Sự kiện bắt đầu trong quy trình biểu diễn điều gì?","options":["Một thuộc tính của thực thể","Điểm khởi phát của một luồng nghiệp vụ","Điểm xóa toàn bộ dữ liệu","Mối quan hệ kế thừa lớp"],"correct":1},{"text":"Điểm khác biệt chính giữa AS-IS và TO-BE là gì?","options":["AS-IS là hiện tại còn TO-BE là quy trình đề xuất","AS-IS chỉ áp dụng cho phần mềm di động","TO-BE chỉ ghi nhận lỗi mạng","Hai sơ đồ luôn phải giống hệt nhau"],"correct":0},{"text":"Khi mô hình quy trình thanh toán, ngoại lệ thanh toán thất bại nên được làm gì?","options":["Bỏ qua vì ít xảy ra","Chuyển thành thuộc tính của khách hàng","Chỉ ghi trong mã nguồn","Thể hiện thành nhánh xử lý phù hợp"],"correct":3},{"text":"Vì sao nên rà soát mô hình quy trình với người thực hiện nghiệp vụ?","options":["Để chọn ngôn ngữ lập trình","Để không cần kiểm thử hệ thống","Để xác minh tính đúng đắn và các bước bị bỏ sót","Để giảm số lượng màn hình thiết kế"],"correct":2}]},{"order":5,"questions":[{"text":"Trong UML, use case thể hiện điều gì?","options":["Cấu trúc bộ nhớ vật lý","Tốc độ kết nối mạng","Mã nguồn của một lớp","Mục tiêu mà tác nhân đạt được khi tương tác với hệ thống"],"correct":3},{"text":"Actor trong sơ đồ use case là gì?","options":["Một phương thức riêng tư","Một lỗi biên dịch","Vai trò bên ngoài tương tác với hệ thống","Một cột của bảng dữ liệu"],"correct":2},{"text":"Quan hệ include trong use case được dùng khi nào?","options":["Một lớp thừa kế lớp cha","Một use case luôn tái sử dụng hành vi chung của use case khác","Hành vi chỉ xảy ra ở tình huống ngoại lệ tùy chọn","Hai tác nhân phải có cùng tên"],"correct":1},{"text":"Quan hệ extend phù hợp trong tình huống nào?","options":["Bổ sung hành vi có điều kiện vào use case cơ sở","Bắt buộc mọi use case phải chạy song song","Định nghĩa khóa ngoại","Thay đổi kiểu dữ liệu của thuộc tính"],"correct":0},{"text":"Tiền điều kiện của một use case mô tả điều gì?","options":["Kết quả sau khi hoàn tất use case","Danh sách toàn bộ lỗi đã sửa","Thời gian bảo hành phần mềm","Điều phải đúng trước khi thực hiện use case"],"correct":3},{"text":"Luồng thay thế trong đặc tả use case mô tả điều gì?","options":["Quy trình triển khai máy chủ","Cấu trúc thư mục dự án","Cách thực hiện hợp lệ khác với luồng chính","Chỉ lệnh tạo cơ sở dữ liệu"],"correct":2},{"text":"Vì sao cần mô tả hậu điều kiện của use case?","options":["Để chọn nhà cung cấp dịch vụ mạng","Để xác định trạng thái sau khi nghiệp vụ kết thúc","Để thay thế mọi điều kiện đầu vào","Để tự động sinh toàn bộ giao diện"],"correct":1}]},{"order":6,"questions":[{"text":"Sơ đồ lớp UML mô tả nội dung nào?","options":["Luồng gói tin trên mạng","Kịch bản kiểm thử tải","Lớp, thuộc tính, phương thức và quan hệ giữa các lớp","Lịch chạy tác vụ hệ điều hành"],"correct":2},{"text":"Ký hiệu 1..* tại đầu quan hệ cho biết điều gì?","options":["Số lượng luôn không giới hạn và có thể bằng không","Có ít nhất một đối tượng tham gia quan hệ","Không đối tượng nào tham gia","Chỉ đúng một đối tượng"],"correct":1},{"text":"Quan hệ kế thừa giữa các lớp diễn tả điều gì?","options":["Lớp con kế thừa đặc điểm từ lớp cha","Một lớp chỉ chứa đúng một thuộc tính","Các lớp không thể tái sử dụng mã","Mỗi lớp luôn dùng một cơ sở dữ liệu riêng"],"correct":0},{"text":"Trong mô hình dữ liệu, khóa chính có vai trò gì?","options":["Lưu mật khẩu dưới dạng văn bản thuần","Chứa hình nền của giao diện","Luôn được phép trùng giá trị","Định danh duy nhất mỗi bản ghi trong bảng"],"correct":3},{"text":"Khóa ngoại có mục đích chính là gì?","options":["Thay thế tất cả chỉ mục","Lưu cấu hình màn hình","Liên kết bản ghi với bảng được tham chiếu","Tự động mã hóa mọi trường"],"correct":2},{"text":"Chuẩn hóa dữ liệu thường nhằm giảm vấn đề nào?","options":["Thời gian học lập trình","Dư thừa và bất nhất dữ liệu","Số lượng màn hình ứng dụng","Số lượng người sử dụng"],"correct":1},{"text":"Nếu một đơn hàng có nhiều chi tiết đơn hàng, quan hệ thông thường là gì?","options":["Một-nhiều giữa đơn hàng và chi tiết đơn hàng","Một-một giữa tất cả bản ghi","Nhiều-nhiều không cần bảng liên kết","Không có quan hệ dữ liệu"],"correct":0}]},{"order":7,"questions":[{"text":"Trong thiết kế hướng đối tượng, nguyên tắc đóng gói giúp điều gì?","options":["Bắt buộc tất cả phương thức là public","Che giấu trạng thái nội bộ và cung cấp giao diện truy cập phù hợp","Cho phép mọi lớp sửa trực tiếp mọi dữ liệu","Loại bỏ nhu cầu kiểm thử"],"correct":1},{"text":"Sequence diagram nhấn mạnh điều gì?","options":["Thứ tự các thông điệp giữa đối tượng theo thời gian","Cấu trúc ổ đĩa cứng","Màu sắc của trang web","Danh sách chức vụ nhân sự"],"correct":0},{"text":"Activation bar trong sequence diagram thể hiện điều gì?","options":["Khoảng trống của bộ nhớ ngoài","Tên bảng dữ liệu","Số lượng người dùng đồng thời","Khoảng thời gian một đối tượng đang thực thi thao tác"],"correct":3},{"text":"Thông điệp trả về trong sequence diagram thường mô tả điều gì?","options":["Dữ liệu luôn được xóa","Tạo mới máy chủ vật lý","Kết quả hoặc quyền điều khiển trả về cho bên gọi","Quy tắc đặt tên lớp"],"correct":2},{"text":"Độ kết dính cao (high cohesion) của một lớp có nghĩa gì?","options":["Tất cả lớp phụ thuộc lẫn nhau","Các trách nhiệm của lớp có liên quan chặt chẽ","Một lớp chịu mọi chức năng của hệ thống","Các phương thức không liên quan nhau"],"correct":1},{"text":"Mức ghép nối thấp (low coupling) mang lại lợi ích gì?","options":["Giảm phụ thuộc giữa các thành phần để dễ thay đổi","Tăng phụ thuộc trực tiếp vào mọi lớp khác","Làm mất khả năng kiểm thử đơn vị","Bắt buộc dùng cơ sở dữ liệu phi quan hệ"],"correct":0},{"text":"Khi thiết kế chức năng đặt hàng, nên tách trách nhiệm thế nào?","options":["Dồn mọi thao tác vào một hàm rất dài","Để giao diện tự sửa bảng dữ liệu trực tiếp","Bỏ qua xử lý lỗi và ngoại lệ","Phân chia kiểm tra đơn, xử lý thanh toán và lưu dữ liệu theo trách nhiệm rõ ràng"],"correct":3}]},{"order":8,"questions":[{"text":"Tài liệu thiết kế chức năng nên mô tả điều gì?","options":["Đầu vào, xử lý, đầu ra và các điều kiện ngoại lệ","Chỉ tên tác giả của tài liệu","Chỉ màu giao diện","Chỉ giá mua máy chủ"],"correct":0},{"text":"Trong kiến trúc nhiều lớp, tầng giao diện thường đảm nhiệm điều gì?","options":["Thay thế toàn bộ tầng dữ liệu","Trực tiếp quản trị thiết bị lưu trữ","Tạo bảng SQL theo mỗi lần nhấn nút","Hiển thị thông tin và tiếp nhận tương tác người dùng"],"correct":3},{"text":"Tầng nghiệp vụ nên đảm nhiệm vai trò nào?","options":["Chỉ cấu hình mạng nội bộ","Chỉ nén các tệp ảnh","Xử lý quy tắc và kiểm tra nghiệp vụ","Chỉ hiển thị màu nút bấm"],"correct":2},{"text":"Validation phía máy chủ cần thiết vì sao?","options":["Vì không cần thông báo lỗi","Để không tin tuyệt đối dữ liệu gửi từ phía người dùng","Vì dữ liệu phía người dùng luôn chính xác","Để loại bỏ hoàn toàn phân quyền"],"correct":1},{"text":"Đối với thao tác thanh toán, tính toàn vẹn giao dịch giúp bảo đảm gì?","options":["Các thay đổi liên quan được ghi nhận nhất quán hoặc hoàn tác","Mỗi bước có thể ghi dữ liệu dang dở tùy ý","Bỏ qua các lỗi kết nối","Tự động làm tăng dung lượng lưu trữ"],"correct":0},{"text":"Đối với API tạo đơn hàng, phản hồi lỗi hợp lý cần có gì?","options":["Chỉ màn hình trống","Luôn trả thành công dù thao tác thất bại","Lộ toàn bộ thông tin bí mật máy chủ","Mã trạng thái phù hợp và thông báo đủ rõ để xử lý"],"correct":3},{"text":"Vì sao cần đối chiếu thiết kế với yêu cầu ban đầu?","options":["Để tránh cần thử nghiệm","Để đổi toàn bộ công nghệ đang dùng","Để phát hiện chức năng thiếu hoặc thiết kế sai mục tiêu","Để bỏ qua tiêu chí chấp nhận"],"correct":2}]}]$bank$::jsonb) LOOP
   SELECT lesson_id INTO STRICT v_lesson FROM lms.lessons
   WHERE course_id=v_course AND lesson_order=(s->>'order')::int AND is_published AND NOT is_deleted;
   -- Do not modify a lesson already having a published quiz of exactly 10 questions.
   IF EXISTS (SELECT 1 FROM assessment.quizzes q WHERE q.lesson_id=v_lesson AND q.is_published AND NOT q.is_deleted
      AND (SELECT count(*) FROM assessment.questions x WHERE x.quiz_id=q.quiz_id)=10) THEN
      CONTINUE;
   END IF;
   SELECT q.quiz_id INTO v_quiz FROM assessment.quizzes q
   WHERE q.lesson_id=v_lesson AND q.course_id=v_course AND NOT q.is_deleted
     AND (SELECT count(*) FROM assessment.questions x WHERE x.quiz_id=q.quiz_id)=3
   ORDER BY q.quiz_id DESC LIMIT 1;
   IF v_quiz IS NULL THEN
      RAISE EXCEPTION 'Expected existing 3-question quiz for lesson %, no safe target found',v_lesson;
   END IF;
   SELECT count(*) INTO v_count FROM assessment.questions WHERE quiz_id=v_quiz;
   IF v_count<>3 THEN RAISE EXCEPTION 'Unexpected count for quiz %: %',v_quiz,v_count; END IF;
   FOR i IN 1..7 LOOP
     item:=s->'questions'->(i-1);
     IF jsonb_array_length(item->'options')<>4 OR (item->>'correct')::int NOT BETWEEN 0 AND 3
       THEN RAISE EXCEPTION 'Invalid question bank, lesson %, question %',v_lesson,i; END IF;
     INSERT INTO assessment.questions (quiz_id,question_text,question_type,question_order,points)
     VALUES (v_quiz,item->>'text','SINGLE_CHOICE',3+i,1) RETURNING question_id INTO v_q;
     FOR j IN 1..4 LOOP
       INSERT INTO assessment.answers (question_id,answer_text,is_correct,answer_order)
       VALUES (v_q,item->'options'->>(j-1),(item->>'correct')::int=j-1,j);
     END LOOP;
   END LOOP;
   UPDATE assessment.quizzes SET is_published=true,
     time_limit_seconds=GREATEST(COALESCE(time_limit_seconds,0),900), updated_at=now()
   WHERE quiz_id=v_quiz;
   IF (SELECT count(*) FROM assessment.questions WHERE quiz_id=v_quiz)<>10
     THEN RAISE EXCEPTION 'Quiz % has unexpected count after update',v_quiz; END IF;
 END LOOP;
END $patch$;
COMMIT;
